pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 targetBurn) internal {
        uint256 before_total;
        try c.totalSupply() returns (uint256 __r) { before_total = __r; } catch { return; }
        uint256 before_balance_self;
        try c.balanceOf(address(this)) returns (uint256 __r) { before_balance_self = __r; } catch { return; }
        bool burn_reverted;
        try c.burn(targetBurn) returns (bool ok) {
            burn_reverted = false;
        } catch {
            burn_reverted = true;
        }
        uint256 after_total;
        try c.totalSupply() returns (uint256 __r) { after_total = __r; } catch { return; }
        uint256 after_balance_self;
        try c.balanceOf(address(this)) returns (uint256 __r) { after_balance_self = __r; } catch { return; }
        assertTrue(( !burn_reverted
                && before_balance_self >= targetBurn
                && after_total == before_total - targetBurn
                && after_balance_self == before_balance_self - targetBurn
            )
            ||
            ( burn_reverted
                && after_total == before_total
                && after_balance_self == before_balance_self
            ));
    }

    function testFuzz_run(uint256 targetBurn) public {
        _run(targetBurn);
    }

    receive() external payable {}
}
